package local.lito381.server;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
/** Real native spell dispatcher, source inventory and original physical calculation. */
public final class TripleDispatchProbe extends NativeMagicalWeaponProbe {
 static void exercise(ClientSession pc,ClientSession peer,GameHub hub,boolean world,int multiplier,Path root,CaptureLog capture)throws Exception{
  reset(pc,peer,hub,world);for(var actor:List.of(pc,peer))set(actor,"sourcePhysicalGrowthStats",SourcePhysicalGrowthStats.classic381());TripleControlProbe.install(multiplier);set(pc,"playerMp",1000);set(pc,"playerMaxMp",1000);set(pc,"playerHp",5000);set(pc,"playerMaxHp",5000);set(peer,"playerHp",1000000);set(peer,"playerMaxHp",1000000);set(pc,"learnedSkills",new HashSet<>(Set.of(132)));((Map<?,?>)get(pc,"spellReadyNanos")).clear();set(pc,"observer",false);set(peer,"observer",false);
  var chars=(List<CharacterSummary>)get(pc,"characters");set(pc,"characters",List.of(copy(chars.get(0),Map.of("type",2,"originalIntelligence",10))));set(pc,"positionX",(int)get(peer,"positionX")-1);set(pc,"positionY",get(peer,"positionY"));
  NativeDeItemPublication.grant(pc,172,1);NativeDeItemPublication.grant(pc,(int)InventoryCatalog.ARROW,100);var item=pc.nativeDeInventory(0).items().stream().filter(i->i.definition().catalogId()==172).findFirst().orElseThrow();NativeDeItemTransaction.call(pc,()->{var next=pc.nativeDeInventory(0).copy();need(!next.toggleWeapon(item.objectId()).isEmpty(),"real bow equip");NativeDeItemApplication.replace(pc,next,0);return null;});var weapon=(SourceWeaponPhysicalStats)call(pc,"activePhysicalWeapon",new Class[]{});need(weapon.bow(),"actual catalog bow");
  var spell=BattleSpellCatalog.tripleArrowSpell(132);var packet=new Protocol.Writer().c(Protocol.C_USE_SPELL).c((132-1)>>3).c((132-1)&7).d(peer.playerObjectId()).h((int)get(peer,"positionX")).h((int)get(peer,"positionY")).bytes();
  var out=System.out;var text=new java.io.ByteArrayOutputStream();try(var wire=new SourceActionPairProbe.Wire(pc,peer);var other=new SourceActionPairProbe.Wire(peer,pc)){
   try{System.setOut(new java.io.PrintStream(text,true,java.nio.charset.StandardCharsets.UTF_8));call(pc,"handle",new Class[]{byte[].class},packet);idle();}finally{System.setOut(out);Files.writeString(root.resolve(world+"-"+multiplier+".log"),text.toString(java.nio.charset.StandardCharsets.UTF_8));}
   String observed=Files.readString((Path)get(capture,"path"))+"\n"+text.toString(java.nio.charset.StandardCharsets.UTF_8);var calculations=observed.lines().filter(line->line.contains("double-damage-multiplier=")).toList();need((int)get(pc,"playerMp")<1000,"actual spell accepted");need(((Map<?,?>)get(pc,"spellReadyNanos")).containsKey(132),"actual cooldown committed");need(CombatTripleArrow.idle(),"dispatcher leaves no triple scope");need(calculations.size()>=3&&calculations.stream().allMatch(line->line.contains("double-damage-multiplier="+multiplier+".0 ")),"all three actual physical paths received configured maximum world="+world+" multiplier="+multiplier);need(pc.nativeDeInventory(0).countCatalog(InventoryCatalog.ARROW)==97,"three attempts consume three arrows");collect(wire);collect(other);need(wire.locked+other.locked==0,"publication outside locks");
  }cases++;
 }
 public static void main(String[]args)throws Exception{
  var base=ServerConfig.load(Path.of(args[0]),"standard");ResourceDatabase.load(base);var f=CombatRules.class.getDeclaredField("current");f.setAccessible(true);TripleControlProbe.original=(CombatRules.Snapshot)f.get(null);var root=Path.of(args[1]);Files.createDirectories(root);
  try{for(boolean world:new boolean[]{false,true})for(int multiplier:new int[]{1,3}){
   var path=root.resolve(world+"-"+multiplier);Files.createDirectories(path);var cfg=copy(base,Map.of("statePersistenceEnabled",false,"stateFile",path.resolve("must-not-write")));var state=new GameStateStore(path.resolve("must-not-write"),false,true);var accounts=new MemoryAccountRepository("fixture","fixture","",0,1,40,52);
   try(var capture=new CaptureLog(path.resolve("capture"));var hub=new GameHub(cfg,state,accounts);var a=new SourceLoginRegression.Fixture(cfg,accounts,state,capture,hub,0,ClientSession.Endpoint.GAME);var p=new SourceLoginRegression.Fixture(cfg,accounts,state,capture,hub,0,ClientSession.Endpoint.GAME);var m=new SourceLoginRegression.Fixture(cfg,accounts,state,capture,hub,0,ClientSession.Endpoint.GAME);var o=new SourceLoginRegression.Fixture(cfg,accounts,state,capture,hub,0,ClientSession.Endpoint.GAME)){
    var clock=(ScheduledExecutorService)get(hub,"battleClock");clock.shutdownNow();need(clock.awaitTermination(2,TimeUnit.SECONDS),"clock stopped");var fixtures=List.of(a,p,m,o);init(fixtures,cfg);FlowRegression.setup(hub,a.session,p.session,m.session,o.session);if(world)world(fixtures,hub);exercise(p.session,m.session,hub,world,multiplier,root,capture);
   }need(!Files.exists(path.resolve("must-not-write")),"memory-only");
  }}finally{f.set(null,TripleControlProbe.original);NativePlayerCommit.closeFixture();}need(NativePlayerLifetime.allIdle()&&CombatTripleArrow.idle(),"all lifetimes released");String result="{\"cases\":"+cases+",\"checks\":"+ownChecks+",\"frames\":"+frames+",\"locked_writes\":"+lockedWrites+"}";Files.writeString(Path.of(args[2]),result);System.out.println(result);
 }
}
